function showPasteNotes(){if(!noteClipboard)return toast('先复制一些音符。');const tid=selectedTrackId,notes=currentSelectedNotes(),at=notes.length?Math.ceil(Math.max(...notes.map(n=>n.start+n.duration))/grid)*grid:selectedClip()?.start||0;modal('粘贴音符',`<p>从应用内复制的 ${noteClipboard.notes.length} 个音符，保持相对时间、长度和力度。不会读取系统剪贴板。</p><label class="modal-label" for="paste-start">粘贴到第几小节（可填小数）</label><input id="paste-start" type="number" min="1" max="${project.bars}" step="0.0625" value="${at/4+1}"><p>音符不会覆盖旧音符。放不下完整音符时会拒绝，不偷偷裁短。</p><div id="paste-error" class="export-progress" role="status"></div>`,'<button class="quiet" data-close>取消</button><button class="accent" id="confirm-paste">粘贴</button>');$('#confirm-paste').onclick=()=>{try{const result=pasteNotes(project,tid,noteClipboard,(+$('#paste-start').value-1)*4);edit(()=>{project=result.project;setNoteSelection(result.ids)});$('#modal').close();revealNoteSelection();toast(`已粘贴 ${result.ids.length} 个独立音符。`)}catch(error){$('#paste-error').textContent=error.message}}}
