$('#editor-content').addEventListener('click',e=>{const id=e.target.closest('button')?.id;if(id==='note-selection-count')revealNoteSelection();if(id==='selection-mode'){noteSelectionMode=!noteSelectionMode;renderNoteTools()}if(id==='select-clip-notes'){setNoteSelection(selectedClip()?notesInClip(track(),selectedClip()).map(n=>n.id):[]);drawPiano();renderInspector()}if(id==='select-track-notes'){setNoteSelection(track().notes.map(n=>n.id));drawPiano();renderInspector()}if(id==='note-list')showNoteList();if(id==='copy-notes')copySelectedNotes();if(id==='paste-notes')showPasteNotes();if(id==='bulk-notes')showBulkNotes();if(id==='delete-selected-notes')deleteSelected();if(id==='chord-input')showChords()});
$('#piano-canvas').addEventListener('keydown',e=>{if($('#modal').open)return;const command=e.metaKey||e.ctrlKey,key=e.key.toLowerCase();if(command&&['a','c','v','d'].includes(key)){e.preventDefault();e.stopPropagation();if(key==='a'){setNoteSelection(track().notes.map(n=>n.id));drawPiano();renderInspector()}if(key==='c')copySelectedNotes();if(key==='v')showPasteNotes();if(key==='d'){try{const notes=currentSelectedNotes();if(!notes.length)return;const deltaBeat=Math.ceil((Math.max(...notes.map(n=>n.start+n.duration))-Math.min(...notes.map(n=>n.start)))/grid)*grid;transformSelection({duplicate:true,deltaBeat})}catch(error){toast(error.message)}}return}if(selectedNoteIds.size&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();e.stopPropagation();try{transformSelection({deltaBeat:e.key==='ArrowLeft'?-(e.shiftKey?4:grid):e.key==='ArrowRight'?(e.shiftKey?4:grid):0,deltaPitch:e.key==='ArrowUp'?(e.shiftKey?12:1):e.key==='ArrowDown'?-(e.shiftKey?12:1):0})}catch(error){toast(error.message)}}});

function showChords(){
 const t=track(),c=selectedClip();if(t.kind==='drum')return toast('和弦需要电钢琴、Pad、拨弦等旋律乐器。');if(!c)return toast('先选一个音块，或用“＋音块”建立区域。');const tid=t.id,cid=c.id,atRevision=revision;let degree=0,preview=null;
 modal('和弦小助手',`<div class="chord-intro">${c.patternId?'<p class="pattern-local-notice">↔ 这是共享块。写入和弦仅修改此块，并自动独立化；其他关联块不改变。</p>':''}<p>在 <strong>${escape(t.name)}</strong> · <strong>${escape(c.name)}</strong> 中写入音符。按照当前 ${escape(project.key)} 自动组合，不用背乐理。</p>${c.muted?'<span class="modal-notice">这个音块已静音，写入音符后仍保持静音。</span>':''}</div><label class="modal-label" for="chord-sequence">一枚和弦，或一段进行</label><select id="chord-sequence"><option value="single">我选一枚和弦</option><option value="warm">温柔循环 · 四个和弦</option><option value="lift">慢慢展开 · 四个和弦</option></select><div id="chord-degrees" class="chord-degrees">${Array.from({length:7},(_,i)=>{const chord=diatonicChord(project.key,i);return`<button data-degree="${i}" class="chord-degree ${i===0?'active':''}" aria-pressed="${i===0}"><strong>${escape(chord.label)}</strong><small>${['I','II','III','IV','V','VI','VII'][i]} · ${chord.quality==='minor'?'小三和弦':chord.quality==='major'?'大三和弦':'减三和弦'}</small></button>`}).join('')}</div><div class="chord-fields"><label>起始小节<input id="chord-start" type="number" min="${c.start/4+1}" max="${(c.start+c.length)/4+1}" step="0.0625" value="${c.start/4+1}"></label><label>总长度（小节）<input id="chord-length" type="number" min="0.0625" max="${c.length/4}" step="0.25" value="${Math.min(1,c.length/4)}"></label><label>写成什么样<select id="chord-mode"><option value="block">一起按下 · 和弦铺底</option><option value="up">逐个向上 · 分解和弦</option><option value="down">逐个向下 · 分解和弦</option></select></label><label>和弦色彩<select id="chord-voices"><option value="triad">三和弦 · 清晰</option><option value="seventh">七和弦 · 多一点色彩</option></select></label></div><details class="chord-advanced"><summary>更多设置 / 音区、转位、分解步长、力度</summary><div class="chord-fields"><label>音区<select id="chord-octave"><option value="2">低音区 · 第 2 八度</option><option value="3" selected>中低音区 · 第 3 八度</option><option value="4">中音区 · 第 4 八度</option><option value="5">高音区 · 第 5 八度</option></select></label><label>转位<select id="chord-inversion"><option value="0">原位 · 从根音开始</option><option value="1">第一转位</option><option value="2">第二转位</option></select></label><label>分解步长<select id="chord-step"><option value="0.25">每 1/4 拍一个音</option><option value="0.5" selected>每半拍一个音</option><option value="1">每拍一个音</option></select></label><label>力度<input id="chord-velocity" type="number" min="1" max="127" value="78"></label></div></details><label class="modal-label" for="chord-insert-mode">怎样写入</label><select id="chord-insert-mode"><option value="add">追加音符，不删除原音符</option><option value="replace">替换这个范围，先备份原工程</option></select><div id="chord-preview" class="chord-preview" aria-live="polite"></div><div id="chord-error" class="export-progress" role="status"></div><div class="modal-notice">这里只预览音符，不播放声音，也不调用模型。写入前不改工程。替换只影响所选时间范围，范围外的长音尾部保留；相邻音块不变。完成后可撤销。</div>`,'<button class="quiet" data-close>取消</button><button class="accent" id="insert-chords">写入音符</button>');
 const plan=()=>{
  if(atRevision!==revision)throw Error('工程已被其他操作修改，请重新打开和弦助手。');
  const sequence=$('#chord-sequence').value,minor=KEYS[project.key].mode==='minor',degrees=sequence==='single'?[degree]:sequence==='warm'?(minor?[0,5,2,6]:[0,4,5,3]):minor?[0,3,5,4]:[0,5,3,4];
  const result=chordPlan(project.key,{degrees,start:(+$('#chord-start').value-1)*4,length:+$('#chord-length').value*4,octave:+$('#chord-octave').value,seventh:$('#chord-voices').value==='seventh',inversion:+$('#chord-inversion').value,mode:$('#chord-mode').value,step:+$('#chord-step').value,velocity:+$('#chord-velocity').value});
  const replace=$('#chord-insert-mode').value==='replace';return{result,replace,options:{clipId:cid,rejectOverlap:true,...(replace?{replaceRange:[result.start,result.start+result.length]}:{})}};
 };
 const update=()=>{try{preview=plan();const {result,options}=preview;insertNotes(project,tid,result.notes,options);$('#chord-error').textContent='';$('#insert-chords').disabled=false;$('#chord-preview').innerHTML=`<span class="eyebrow">音符预览 · 不发声</span><h3>${result.labels.map(escape).join(' → ')}</h3><p>${result.chords.map(chord=>`${escape(chord.label)}：${chord.pitches.map(noteName).join(' / ')}`).join('<br>')}</p><div class="chord-note-map" style="--track-color:${t.color}">${clipSVG({notes:result.notes},result.start,result.start+result.length)}</div><small>${result.notes.length} 个新音符 · ${+((result.length)/4).toFixed(3)} 小节 · ${preview.replace?'替换选中范围，先备份':'追加，不删除原音符'}</small>`}catch(error){preview=null;$('#chord-error').textContent=error.message;$('#insert-chords').disabled=true;$('#chord-preview').innerHTML='<span class="eyebrow">待调整</span><p>修改位置、长度或写入方式后，可查看完整的和弦预览。</p>'}};
 $$('#modal-content input').forEach(input=>input.addEventListener('input',update));
 $$('#modal-content input,#modal-content select').forEach(input=>input.addEventListener('change',()=>{if(input.id==='chord-sequence'){const sequence=input.value;$('#chord-degrees').hidden=sequence!=='single';$('#chord-length').value=sequence==='single'?Math.min(1,c.length/4):c.length/4}update()}));
 $$('[data-degree]').forEach(button=>button.onclick=()=>{degree=+button.dataset.degree;$$('[data-degree]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',b===button)});update()});
 $('#insert-chords').onclick=async()=>{if(!preview)return;try{const latest=plan(),next=insertNotes(project,tid,latest.result.notes,latest.options),action=()=>{edit(()=>{project=next.project;setNoteSelection(next.ids)});revealNoteSelection();toast(`已写入 ${next.ids.length} 个和弦音符，可以继续批量编辑。`)};$('#modal').close();if(latest.replace)await protectedChange(action,'写入和弦前 · '+project.name);else action()}catch(error){$('#chord-error').textContent=error.message}};
 update();
}

function seekWorkspace(beat,bar){if(candidatePreview)stop();const r=normalizeRange(playbackOptions().range,project.bars*4);if(beat<r.start||beat>=r.end)return toast('定位不在当前练习范围内。可先点“整首范围”。');if(engine.playing)playWorkspace(beat).catch(e=>toast(e.message));else engine.offset=beat;status(`已定位到第 ${bar} 小节。`)}
$('#arrangement').addEventListener('click',e=>{if(suppressClipClick){suppressClipClick=false;return}const mute=e.target.closest('[data-mute]'),solo=e.target.closest('[data-solo]');if(mute||solo){mixToggle(mute||solo);return}const info=e.target.closest('[data-select-track]'),clip=e.target.closest('[data-clip]'),bar=e.target.closest('[data-bar]');if(info)selectTrack(info.dataset.selectTrack);if(clip)focusClip(clip.dataset.clipTrack,clip.dataset.clip);if(bar)seekWorkspace(+bar.dataset.bar*4,+bar.dataset.bar+1)});
$('#arrangement').addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.dataset.selectTrack){e.preventDefault();e.stopPropagation();selectTrack(e.target.dataset.selectTrack)}const b=e.target.closest('[data-clip]');if(b&&['ArrowLeft','ArrowRight','Delete','Backspace'].includes(e.key)){e.preventDefault();e.stopPropagation();selectedTrackId=b.dataset.clipTrack;selectedClipId=b.dataset.clip;const c=selectedClip();if(e.key==='Delete'||e.key==='Backspace'){protectedChange(()=>edit(()=>project=removeClip(project,selectedTrackId,c.id)),'删除音块前 · '+project.name)}else edit(()=>project=moveClip(project,selectedTrackId,c.id,c.start+(e.key==='ArrowRight'?1:-1)*(e.shiftKey?grid:4)).project);$('#arrangement').querySelector(`[data-clip="${selectedClipId}"]`)?.focus()}});
$('#arrangement').addEventListener('dblclick',e=>{const lane=e.target.closest('[data-lane-track]');if(!lane||e.target.closest('[data-clip]'))return;const beat=Math.floor((e.clientX-lane.getBoundingClientRect().left)/lane.clientWidth*project.bars*4/4)*4;edit(()=>{const result=createClip(project,lane.dataset.laneTrack,beat,Math.min(4,project.bars*4-beat));project=result.project;selectedTrackId=lane.dataset.laneTrack;selectedClipId=result.clipId});renderEditor()});
$('#arrangement').addEventListener('pointerdown',e=>{const b=e.target.closest('[data-clip]');if(!b||e.button!==0)return;const lane=b.closest('.track-lane'),t=project.tracks.find(t=>t.id===b.dataset.clipTrack),c=t.clips.find(c=>c.id===b.dataset.clip);clipDrag={element:b,lane,trackId:t.id,clipId:c.id,before:copy(project),x:e.clientX,width:lane.clientWidth,start:c.start,length:c.length,resize:!!e.target.closest('.clip-handle'),duplicate:e.altKey,moved:false,nextStart:c.start,nextLength:c.length};b.setPointerCapture(e.pointerId)});
$('#arrangement').addEventListener('pointermove',e=>{const d=clipDrag;if(!d)return;const delta=(e.clientX-d.x)/d.width*project.bars*4;if(!d.moved&&Math.abs(e.clientX-d.x)<5)return;d.moved=true;d.element.classList.add('clip-dragging');if(d.resize)d.nextLength=clamp(Math.round((d.length+delta)/grid)*grid,.25,project.bars*4-d.start);else d.nextStart=clamp(Math.round((d.start+delta)/grid)*grid,0,project.bars*4-d.length);d.element.style.left=`calc(${d.nextStart/(project.bars*4)*100}% + 3px)`;d.element.style.width=`calc(${d.nextLength/(project.bars*4)*100}% - 6px)`;status(`${d.resize?'调整长度':d.duplicate?'复制到':'移动到'}：第 ${+(d.nextStart/4+1).toFixed(2)} 小节 · ${+(d.nextLength/4).toFixed(2)} 小节长`)});
function endClipDrag(cancel=false){const d=clipDrag;if(!d)return;clipDrag=null;if(d.moved){suppressClipClick=true;setTimeout(()=>suppressClipClick=false,350);if(!cancel)edit(()=>{selectedTrackId=d.trackId;selectedClipId=d.clipId;if(d.resize)project=resizeClip(project,d.trackId,d.clipId,d.nextLength);else{const result=moveClip(project,d.trackId,d.clipId,d.nextStart,{duplicate:d.duplicate});project=result.project;selectedClipId=result.clipId}});else renderArrangement()} }
$('#arrangement').addEventListener('pointerup',()=>endClipDrag());$('#arrangement').addEventListener('pointercancel',()=>endClipDrag(true));
$('#clip-controls').addEventListener('click',e=>{const action=e.target.closest('[data-clip-action]')?.dataset.clipAction,c=selectedClip();if(!action)return;if(action==='add'){const start=firstClipSpace(track(),4,project.bars*4);if(start===null)return toast('当前轨道没有一小节空位。可先删除音块或延长工程。');edit(()=>{const result=createClip(project,selectedTrackId,start);project=result.project;selectedClipId=result.clipId});return}if(!c)return;if(action==='phrase-transform')return showPhraseTransform();if(action==='performance')return showPerformance('clip');if(action==='pattern-save')return patternUI.capture();if(action==='pattern-open')return patternUI.shared(c.patternId);if(action==='pattern-transform')return patternUI.transform(c.patternId);if(action==='pattern-detach')return patternUI.detach();if(action==='copy'){const start=firstClipSpace(track(),c.length,project.bars*4,c.start+c.length);if(start===null)return toast('没有足够空位。先删去一个音块或延长工程，再复制。');edit(()=>{const result=moveClip(project,selectedTrackId,c.id,start,{duplicate:true});project=result.project;selectedClipId=result.clipId});return}if(action==='split'){const point=c.start+Math.round(c.length/2/grid)*grid;edit(()=>{const result=splitClip(project,selectedTrackId,c.id,point);project=result.project;selectedClipId=result.clipId});return}if(action==='mute'){edit(()=>c.muted=!c.muted);return}if(action==='repeat')showRepeatedCopies();if(action==='preview')previewSelectedClip();if(action==='range')changeRange({start:c.start,end:c.start+c.length});if(action==='settings')showClipSettings()});
function showClipSettings(){const c=selectedClip(),tid=selectedTrackId,cid=c.id;modal('音块设置',`<label class="modal-label" for="clip-name">名称</label><input id="clip-name" value="${escape(c.name)}" maxlength="40"><div class="clip-fields"><label>起始小节<input id="clip-start" type="number" min="1" max="${project.bars}" step="0.0625" value="${c.start/4+1}"></label><label>长度（小节）<input id="clip-length" type="number" min="0.0625" max="${project.bars}" step="0.0625" value="${c.length/4}"></label></div><p>移动会带走音符；复制后的音块独立编辑。缩短会裁掉尾部，延长只增加空白，不会自动重复。</p><div id="clip-error" class="export-progress"></div>`,'<button class="danger" id="delete-clip-action">删除音块</button><button class="accent" id="save-clip-action">保存</button>');$('#save-clip-action').onclick=()=>{try{const next=updateClip(project,tid,cid,{start:(+$('#clip-start').value-1)*4,length:+$('#clip-length').value*4,name:$('#clip-name').value.trim(),muted:c.muted});edit(()=>project=next);$('#modal').close()}catch(error){$('#clip-error').textContent=error.message}};$('#delete-clip-action').onclick=()=>confirmDialog('删除这个音块？','会删除这个音块及其内部音符，其他音块不受影响。可以撤销。',()=>protectedChange(()=>{edit(()=>project=removeClip(project,tid,cid));toast('音块与内部音符已删除，可撤销。')},'删除音块前 · '+project.name),'删除音块')}
function mixToggle(button){const isMute=!!button.dataset.mute,id=button.dataset.mute||button.dataset.solo;edit(()=>{const t=project.tracks.find(t=>t.id===id);if(t)t[isMute?'muted':'solo']=!t[isMute?'muted':'solo']},{mixOnly:true});status(isMute?'M 是静音，S 是只听这条轨道。':'独奏已更新。可以同时独奏多个轨道。')}
$('#mixer-content').addEventListener('click',e=>{const sound=e.target.closest('[data-sound-track]');if(sound)return showSound(sound.dataset.soundTrack);const b=e.target.closest('[data-mute],[data-solo]');if(b)mixToggle(b)});
$('#mixer-content').addEventListener('input',e=>{const id=e.target.dataset.volume||e.target.dataset.pan;if(!id)return;gestureBefore||=copy(project);const t=project.tracks.find(t=>t.id===id);if(e.target.dataset.volume){t.volume=+e.target.value/100;e.target.closest('.mixer-strip').querySelector('.mixer-volume').textContent=e.target.value+'%'}else t.pan=+e.target.value/100;engine.updateMix(project)});
$('#mixer-content').addEventListener('change',e=>{if(!e.target.dataset.volume&&!e.target.dataset.pan)return;record(gestureBefore||project);gestureBefore=null;afterEdit({mixOnly:true})});
$('#drum-content').addEventListener('change',e=>{if(e.target.id==='drum-bar-select'){drumBar=+e.target.value;renderDrums()}});
$('#drum-content').addEventListener('click',e=>{const nav=e.target.closest('[data-drum-nav]');if(nav){drumBar=clamp(drumBar+(nav.dataset.drumNav==='next'?1:-1),0,project.bars-1);renderDrums();return}const bar=e.target.closest('[data-drum-bar]'),step=e.target.closest('[data-step]');if(bar){drumBar=+bar.dataset.drumBar;renderDrums()}if(step){const t=project.tracks.find(t=>t.id===step.dataset.stepTrack),start=drumBar*4+(+step.dataset.step)*.25;edit(()=>{const old=t.notes.find(n=>Math.abs(n.start-start)<.01);if(old)t.notes=t.notes.filter(n=>n!==old);else t.notes.push({id:uid(),pitch:INSTRUMENTS[t.instrument].pitch,start,duration:.125,velocity:t.instrument==='hat'?65:95})});engine.previewNote(t.instrument,INSTRUMENTS[t.instrument].pitch,80,t.sound,t.sampler).catch(e=>toast(e.message))}if(e.target.closest('#copy-drum-bar')){edit(()=>{for(const t of project.tracks.filter(t=>t.kind==='drum')){const pattern=t.notes.filter(n=>n.start>=drumBar*4&&n.start<(drumBar+1)*4).map(n=>({...n,start:n.start-drumBar*4}));t.notes=Array.from({length:project.bars},(_,b)=>pattern.map(n=>({...n,id:uid(),start:n.start+b*4}))).flat()}});toast('这一小节的鼓已复制到所有小节。')}});
$('.editor-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b)switchTab(b.dataset.tab)});
$('#piano-keys').addEventListener('click',e=>{const b=e.target.closest('[data-pitch]');if(b)engine.previewNote(track().instrument,+b.dataset.pitch,80,track().sound,track().sampler).catch(e=>toast(e.message))});
$('#grid-select').addEventListener('change',e=>{grid=+e.target.value;drawPiano()});$('#quantize-btn').addEventListener('click',()=>{const ids=selectedNoteIds.size?[...selectedNoteIds]:track().notes.map(n=>n.id);if(!ids.length)return;edit(()=>project=transformNotes(project,selectedTrackId,ids,{quantize:grid}).project)});
$('#clear-notes').addEventListener('click',()=>confirmDialog('清空这个轨道？',`只会清空“${track().name}”的音符，不影响其他轨道。之后也可以撤销。`,()=>protectedChange(()=>{edit(()=>track().notes=[]);toast('此轨音符已清空，可撤销。')},'清空轨道前 · '+project.name)));
$('#play-btn').addEventListener('click',togglePlay);$('#stop-btn').addEventListener('click',stop);$('#loop-btn').addEventListener('click',()=>{const beat=engine.beat;engine.loop=!engine.loop;$('#loop-btn').classList.toggle('active',engine.loop);$('#loop-btn').setAttribute('aria-pressed',engine.loop);if(engine.playing)(candidatePreview?engine.play(candidate.project,beat,{range:null}):playWorkspace(beat)).catch(e=>toast(e.message))});$('#metro-btn').addEventListener('click',()=>{engine.metronome=!engine.metronome;$('#metro-btn').classList.toggle('active',engine.metronome);$('#metro-btn').setAttribute('aria-pressed',engine.metronome)});
$('#tempo').addEventListener('change',e=>edit(()=>project.bpm=clamp(+e.target.value||86,40,200)));$('#key-select').addEventListener('change',e=>edit(()=>project=transposeProject(project,e.target.value)));$('#bars-select').addEventListener('change',e=>{const bars=+e.target.value;e.target.value=project.bars;showLength(bars)});
function commitProjectName(){const input=$('#project-name'),name=input.value.trim().slice(0,60)||'未命名作品';if(name!==project.name)edit(()=>project.name=name,{restart:false});input.value=name}
$('#project-name').addEventListener('change',commitProjectName);$('#project-name').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();commitProjectName();e.currentTarget.blur()}});
for(const id of ['swing','master-volume']){$('#'+id).addEventListener('input',e=>{gestureBefore||=copy(project);if(id==='swing'){project.swing=+e.target.value;$('#swing-value').textContent=e.target.value+'%'}else{project.master=+e.target.value/100;engine.updateMix(project)}});$('#'+id).addEventListener('change',()=>{record(gestureBefore||project);gestureBefore=null;afterEdit({mixOnly:id==='master-volume'})})}
