function chooseStyle(style){const make=async()=>{await replaceProject(generateProject({style,key:project.key,bars:project.bars,seed:Math.floor(Math.random()*1e7)}),{backupLabel:'换风格前',message:`已换成 ${STYLES.find(s=>s.id===style).name}。原来的版本可以撤销。`});$('.beginner-steps small').textContent='已选择 '+STYLES.find(s=>s.id===style).name};confirmDialog('换一个创作起点？','会替换当前编曲。你的旧版本会保留在撤销历史中；重要作品建议先保存工程文件。',make,'生成新起点')}
$('#style-list').addEventListener('click',e=>{const b=e.target.closest('[data-style]');if(b)chooseStyle(b.dataset.style)});
$('#mobile-style-select').addEventListener('change',e=>{chooseStyle(e.target.value);e.target.value=project.style});
function modal(title,body,footer=''){const d=$('#modal');$('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-close aria-label="关闭窗口">×</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!d.open)d.showModal();return d}
$('#modal').addEventListener('click',e=>{if(e.target.closest('[data-close]'))$('#modal').close();if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
function confirmDialog(title,message,fn,label='确认'){modal(title,`<p>${escape(message)}</p>`,'<button class="quiet" data-close>取消</button><button class="accent" id="confirm-action">'+escape(label)+'</button>');$('#confirm-action').onclick=async()=>{$('#modal').close();try{await fn()}catch(error){toast(error.message)}}}
function download(bytes,filename,type){const blob=bytes instanceof Blob?bytes:new Blob([bytes],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
const filename=()=>project.name.replace(/[\\/:*?"<>|]/g,'-').trim()||'我的作品';
function projectFilename(p){return String(p.name||'Sprout 作品').replace(/[\\/:*?"<>|]/g,'_').slice(0,60)}
function versionDate(time){try{return new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date(time))}catch{return'未知时间'}}
let versionsRequest=0;
async function showVersions(){
 const request=++versionsRequest;modal('本机版本与恢复','<div class="versions-loading">正在读取保存点…</div>');
 try{
  const rows=await vault.list();if(request!==versionsRequest||!$('#modal').open||$('#modal-content h2')?.textContent!=='本机版本与恢复')return;
  modal('本机版本与恢复',`<div class="version-intro"><p>先预览，再恢复。恢复之前也会保存当前版本。</p><span>仅此浏览器 · 不是云备份</span><p id="history-persistence">${escape($('#save-status').title||'刷新历史最多各 8 步，共享 1.5 MiB。')}</p></div><div class="checkpoint-form"><input id="checkpoint-name" aria-label="保存点名称" maxlength="60" placeholder="比如：第一版和弦、喜欢的鼓点"><button id="create-checkpoint" class="accent">保存当前版本</button></div><div id="version-error" class="export-progress" role="status"></div><div class="version-browser"><div class="version-list">${rows.length?rows.map(row=>`<button class="version-row ${row.valid?'':'invalid'}" data-version-id="${escape(row.id)}" ${row.valid?'':'data-damaged="true"'}><strong>${escape(row.label)}</strong><span>${row.summary?escape(row.summary.name):'数据损坏 · 暂时无法打开'}</span><small>${versionDate(row.createdAt)}${row.summary?` · ${row.summary.bars} 小节 · ${row.summary.notes} 音符`:''}</small></button>`).join(''):'<p class="empty-versions">还没有保存点。给喜欢的版本起个名字。</p>'}</div><div id="version-preview" class="version-preview"><span class="eyebrow">先看看这一版</span><p>选左侧一个版本，可以查看每条轨道和音块，不会播放声音，也不会改动工作区。</p></div></div><div class="modal-notice">编辑时每分钟留一个自动版本；最多保留最近 ${LIMITS.versions} 个版本，保存点数据总量不超过 8 MiB。达到上限会移除最早版本。刷新后最多恢复 8 步撤销 / 重做历史，较大工程按容量裁剪。永久备份请下载工程文件。</div>`);
  $('#create-checkpoint').onclick=async()=>{const b=$('#create-checkpoint'),at=revision;b.disabled=true;try{if(storageConflict)throw new StorageConflict();const result=await vault.checkpoint(project,$('#checkpoint-name').value.trim()||'我的保存点',{history,future});if(at===revision){savedRevision=at;committedStatus(result,'保存点已保存 · 版本');if(warningMode==='error')clearSaveWarning()}toast('保存点已写入本机版本库。');await showVersions()}catch(error){$('#version-error').textContent=error.message;saveError(error,writeRecovery());b.disabled=false}};
  let previewRequest=0;$$('.version-row').forEach(button=>button.onclick=async()=>{
   const previewAt=++previewRequest,target=$('#version-preview');try{if(button.dataset.damaged){const raw=await vault.getRaw(button.dataset.versionId);if(!target.isConnected||previewAt!==previewRequest)return;target.innerHTML='<p>这个版本未通过校验，不能直接恢复。可以下载原始 JSON，交给开发者排查或自行修复。</p><button id="download-damaged-version" class="quiet">下载原始数据</button>';$('#download-damaged-version').onclick=()=>download(raw,'sprout-damaged-record.json','application/json');return}const version=await vault.get(button.dataset.versionId),summary=projectSummary(version),current=projectSummary(project);if(!target.isConnected||previewAt!==previewRequest)return;
    $$('.version-row').forEach(b=>b.classList.toggle('selected',b===button));
    target.innerHTML=`<span class="eyebrow">版本预览 · 不发声</span><h3>${escape(version.name)}</h3><div class="version-stats"><span>${version.bpm} BPM</span><span>${escape(version.key)}</span><span>${version.bars} 小节</span><span>${summary.notes} 音符</span></div><div class="version-differences">${version.bpm!==project.bpm?`速度 ${project.bpm} → ${version.bpm} · `:''}${version.key!==project.key?`调性 ${escape(project.key)} → ${escape(version.key)} · `:''}轨道 ${current.tracks} → ${summary.tracks} · 音符 ${current.notes} → ${summary.notes}</div><div class="version-track-list">${version.tracks.map(t=>`<div class="version-track" style="--track-color:${t.color}"><strong>${escape(t.name)}</strong><span>${t.clips.length} 音块 · ${t.notes.length} 音符${t.muted?' · 轨道静音':''}</span><div class="version-note-map">${clipSVG(t,0,version.bars*4)}</div></div>`).join('')}</div><div class="version-preview-actions"><button id="restore-version" class="accent">恢复这个版本</button><button id="download-version" class="quiet">下载工程</button></div>`;
    $('#download-version').onclick=()=>download(JSON.stringify(version,null,2),projectFilename(version)+'-保存点.sprout','application/json');
    $('#restore-version').onclick=()=>confirmDialog('恢复这个版本？',`恢复“${version.name}”。当前“${project.name}”会先写入本机保存点，再替换工作区。`,async()=>{const changed=await replaceProject(version,{backupLabel:'恢复版本前',message:'版本已恢复。刚才的内容也在本机版本库里。'});if(changed)stop()},'保存当前并恢复');
   }catch(error){target.textContent='版本无法打开：'+error.message}
  });
 }catch(error){modal('本机版本与恢复',`<p>${escape(error.message)}</p><p>请先导出当前工程文件，编辑内容仍保留在工作区。</p>`,'<button class="accent" id="version-fallback-download">导出当前工程</button>');$('#version-fallback-download').onclick=saveProject}
}
