$('#import-midi-file').addEventListener('change',async e=>{
 const file=e.target.files[0];if(!file)return;
 try{if(file.size>5e6)throw Error('MIDI 文件不能超过 5 MB');const {project:imported,report}=decodeMIDI(await file.arrayBuffer(),{name:file.name});
  modal('导入 MIDI · 先看一下',`<p><strong>${escape(imported.name)}</strong><br>${report.tracks} 个轨道 · ${report.importedNotes} / ${report.sourceNotes} 个音符 · ${report.bars} 小节 · ${report.bpm} BPM</p><ul class="import-warnings">${report.warnings.map(w=>`<li>${escape(w)}</li>`).join('')}</ul><div class="modal-notice">导入会替换当前工作区，可以撤销。没有自动转调或对齐网格；原音符拍位置保留。较长文件仅导入前 64 小节。可先保存当前工程。</div>`,'<button class="quiet" data-close>取消</button><button class="accent" id="confirm-midi-import">按以上说明导入</button>');
  $('#confirm-midi-import').onclick=async()=>{stop();const changed=await replaceProject(imported,{backupLabel:'导入 MIDI 前',message:`已导入 ${report.importedNotes} 个音符。音色使用内置映射，可撤销。`});if(changed)$('#modal').close()};
 }catch(error){toast('MIDI 导入失败：'+error.message)}finally{e.target.value=''}
});
$('#track-options').addEventListener('click',()=>{const t=track(),selected=t.id,at=revision;modal('轨道与乐器',`<label class="modal-label" for="track-name-setting">轨道名称</label><input id="track-name-setting" type="text" value="${escape(t.name)}" maxlength="40"><label class="modal-label" for="track-instrument-setting">内置音源</label><select id="track-instrument-setting">${Object.entries(INSTRUMENTS).filter(([id,i])=>i.kind===t.kind).map(([id,i])=>`<option value="${id}" ${id===t.instrument?'selected':''}>${i.name}</option>`).join('')}</select><div class="modal-notice">换音源会保留音符。鼓轨换成另一种鼓时，会使用对应的鼓音高。轨道名称不影响发声。更换音源会恢复新音源的原始音色；鼓共享块换鼓种会独立化，源乐句不变。</div>`,'<button id="delete-track-action" class="danger">删除这条轨道</button><button id="save-track-setting" class="accent">保存</button>');$('#delete-track-action').disabled=project.tracks.length<=1;$('#save-track-setting').onclick=()=>{if(at!==revision)return toast('工程已改变，请重新打开轨道设置。');const name=$('#track-name-setting').value.trim().slice(0,40)||t.name,instrument=$('#track-instrument-setting').value;if(edit(()=>project=changeTrackInstrument(project,selected,instrument,{name}))){$('#modal').close();toast(instrument===t.instrument?'轨道设置已更新。':'新音源已应用，音色恢复原始设置，可撤销。')}};$('#delete-track-action').onclick=()=>confirmDialog('删除这条轨道？',`会移除“${t.name}”及其音符，其他轨道不受影响。可以用撤销找回。`,()=>protectedChange(()=>{edit(()=>project.tracks=project.tracks.filter(t=>t.id!==selected));toast('轨道已移除，可撤销。')},'删除轨道前 · '+project.name),'删除轨道')});
